$(document).ready(function() {
    function GetisErrorPage(isPageLoaded) {
        var objWithoutNumber = {
            event: "pageLoaded",
            _maruti: {
                userInfo: {
                    authenticatedState: "Unauthenticated"
                },
                identities: {
                    ecid: ecidupdate
                }
            },
            web: {
                webPageDetails: {
                    URL: document.location.href,
                    name: pageName,
                    server: document.location.hostname,
                    siteSection: $.trim($("[id*=Adobegchannel]").val()),
                    isErrorPage: isPageLoaded
                }
            }
        };
        window.adobeDataLayer.push(objWithoutNumber)
    }
    $.ajax({
        url: document.location.href,
        method: "GET",
        success: function() {
            GetisErrorPage(!1)
        },
        error: function(jqXHR) {
            jqXHR.status === 404 ? GetisErrorPage(!0) : GetisErrorPage(!0)
        }
    })
});
